    /// <summary>Re-runs the search and updates the visible rows, keeping row VMs (and their expanded state) stable.</summary>
    private void Refresh()
    {
        if (IsHistoryMode) RefreshHistory();
        else RefreshSnippets();

        SelectedSnippet = Filtered.Count > 0 ? Filtered[0] : null;
        UpdateOffer();
    }

    /// <summary>
    /// Decides whether the line that was just searched for should also be offered as
    /// something to run.
    ///
    /// An item that matches beats the offer — but only where the line could have been
    /// meant as a search for that item. "lock" could: a snippet called "Lock the server
    /// room door" answers to it, and keeps it a filter. <c>D:\work\tools\</c> could not,
    /// and a snippet whose body merely mentions that folder has not been asked for by
    /// someone typing the folder's own path.
    ///
    /// An item also wins when it <em>is</em> the line — a snippet whose text is the very
    /// link you typed was plausibly the thing you were looking for, however literal the
    /// line. Merely mentioning it is not being it.
    ///
    /// The one place all of that is dropped is the clipboard history, where the clips
    /// themselves are mostly paths and links: there a line that looks like one is far more
    /// likely to be someone hunting for the clip they copied than an instruction, so a
    /// matching clip wins whatever was typed.
    ///
    /// A line that names a define in the variables file is offered as each of its values
    /// as well, below whatever the line itself was offered as — see
    /// <see cref="UnmatchedSearch.PlanDefine"/>. Those stand the way quit does: a matching
    /// row does not take them away, and does keep the selection.
    /// </summary>
    private void UpdateOffer()
    {
        // Klippy's own quit, ahead of the gate below and deliberately outside it: that
        // setting governs handing typed text to the machine, and closing the app is
        // neither typed text nor the machine's business. Unlike the rest of this method, no
        // matching item beats it here: the footer link and the tray are the only other ways
        // out, and a snippet that merely mentions "quit" — in its label, content or tag —
        // must not silently take the keyboard route away. A matching row still keeps the
        // selection and answers to Enter, exactly as it does beside any other offer; it is
        // only the offer's own standing that stops depending on the list being empty.
        if (CanQuit && Names(FilterText, QuitWord))
        {
            ShowOffers([OfferViewModel.Quit()], takeSelection: false);
            return;
        }

        if (!_prefs.ExecuteUnmatched || !CanExecuteUnmatched)
        {
            ShowOffers([], takeSelection: false);
            return;
        }

        // Only a rooted path ever reaches the file system here, so an ordinary search word
        // costs the same as it did when this ran on an empty list alone — unless it is the
        // name of a define, which is what asks for the values it stands for to be looked at.
        //
        // The same environment a marked item is resolved against, variables file included:
        // two routes to the same launcher must not disagree about what %ws% means any more
        // than about what %LOCALAPPDATA% does.
        var variables = KlippyVariables.Current;
        var environment = variables.Ahead(EnvironmentProbe.Real);
        var plans = new List<ExecutionPlan>();

        // A line that is the name of a define, offered as each value it stands for.
        // Snippets only: in the history a line is someone hunting for a clip, and a name is
        // no less likely to be that than a path is.
        var defines = IsHistoryMode
            ? []
            : UnmatchedSearch.PlanDefine(FilterText, variables, _prefs.ExecuteVerifyPaths,

        : UnmatchedSearch.PlanDefine(FilterText, variables, _prefs.ExecuteVerifyPaths,
            environment: environment, alsoOpens: _prefs.AlsoOpens);

    // Standing beside a list that still has rows in it, what the line itself names is
    // what Enter acts on — so the selection comes off the list, since a row that is not
    // getting the keystroke must not sit there wearing the badge that says it is. ↓
    // moves back in, and from there Enter activates the row as it always did.
    //
    // Where that is one of the define's own offers — %klippy% resolved to one of
    // klippy's values — the define's order stands in for it, so %klippy% and klippy put
    // the same thing on Enter. Anything else it named keeps its place at the top:
    // adding a define never changes what Enter did to a line before it.
    bool takeSelection = false;
    var plan = UnmatchedSearch.Plan(FilterText, _prefs.ExecuteVerifyPaths, environment: environment);
    if (plan.Kind != ExecutionKind.None)
    {
        bool beatenByAMatch = Filtered.Count > 0
                              && (IsHistoryMode || UnmatchedSearch.CouldBeASearch(plan) || AnItemIsTheLine(plan));
        takeSelection = !beatenByAMatch;
        if (takeSelection && !defines.Any(d => UnmatchedSearch.IsSame(d, plan))) plans.Add(plan);
    }

    // After the line's own offer, and not a reason to take the selection from a row, the
    // way quit is not: a bare name is an ordinary word — "app" is a search as often as
    // it is anything — and every snippet written with %app% in it answers to it. Being
    // shown is the whole of what a name is owed here: ↑ from the top row reaches it.
    foreach (var value in defines)
        if (!plans.Exists(p => UnmatchedSearch.IsSame(p, value)))
            plans.Add(value);

    ShowOffers(plans.ConvertAll(p => new OfferViewModel(p)), takeSelection);
}

/// <summary>
/// Puts up what the line is offered as, in place of whatever was before. The top offer
/// holds the selection whenever no row does — which, with nothing matching, is always —
/// and <paramref name="takeSelection"/> says whether it takes the selection from a row.
/// </summary>
private void ShowOffers(IReadOnlyList<OfferViewModel> offers, bool takeSelection)
{
    // Every keystroke comes through here, and nearly every one with nothing on offer
    // either side of it: nothing to tell the view.
    if (Offers.Count > 0 || offers.Count > 0)
    {
        Offers.Clear();
        foreach (var offer in offers)
        {
            // Numbered only where there is a choice to make, and only as far as a digit goes.
            if (offers.Count > 1 && Offers.Count < NumberedOffers) offer.Number = Offers.Count + 1;
            Offers.Add(offer);
        }
        OnPropertyChanged(nameof(Offer));
        OnPropertyChanged(nameof(HasOffers));
    }

    _offerIndex = 0;
    if (takeSelection && Offers.Count > 0) SelectedSnippet = null;
    SyncOfferSelection();
}

