{
    SyncOfferSelection();
    UpdateSelectedImage();
}

/// <summary>How many offers <c>Ctrl/⌘</c> and a digit reach: the top nine, 1 to 9.</summary>
public const int NumberedOffers = 9;

/// <summary>
/// Runs the offer that carries <paramref name="number"/> — <c>Ctrl/⌘+2</c> for the second
/// band — exactly as clicking it would, a machine control's confirmation included, and
/// whichever band or row holds the selection, which it leaves where it is. False when no
/// band carries that number: there is no second band, or only one band and so nothing to
/// choose between, and the key is left to whatever else wants it.
/// </summary>
public bool RunNumberedOffer(int number)
{
    if (number < 1 || Offers.FirstOrDefault(o => o.Number == number) is not { } offer) return false;
    RunOfferCommand.Execute(offer);
    return true;
}

/// <summary>
/// Tells each offer whether it is the one holding the selection, after anything that
/// could have moved it: a row taking it, the offers changing, or the arrows.
/// </summary>
private void SyncOfferSelection()
{
    var selected = SelectedOffer;
    foreach (var offer in Offers) offer.IsSelected = ReferenceEquals(offer, selected);
    OnPropertyChanged(nameof(SelectedOffer));
    OnPropertyChanged(nameof(IsOfferSelected));
}

private void RefreshSnippets()
{
    // "code argument…" invokes one snippet rather than filtering the list: the search
    // box has become a command line, so the words after the code are arguments for
    // its %P% placeholders and not search terms.
    if (TryInvoke()) return;

    ClearArguments();
    var results = _store.Search(FilterText);

    Filtered.Clear();
    foreach (var entry in results)
    {
        if (_activeTag != AllTag && !string.Equals(entry.Item.Tag, _activeTag, StringComparison.OrdinalIgnoreCase))
            continue;

        Filtered.Add(RowFor(entry.Item));
    }

    SnippetCountText = Filtered.Count == 1 ? "1 snippet" : $"{Filtered.Count} snippets";
}

/// <summary>
/// Shows just the snippet whose quick-code was typed, carrying whatever was typed
/// after it. False when the line is not an invocation — no whitespace yet, or no
/// snippet answers to that exact code — and the ordinary search runs instead.
///
/// The variables file comes along, so an argument can name a define rather than
/// spelling a path out: "r app" is the solution app names. Against the snippet as
/// stored, because the item is half of the question — its %P:file% is what says which
/// flavour of a name it wants. Resolved once, here, so the row's preview, a copy and a
/// run all see the same argument: having them disagree about what a word meant would
/// be worse than not resolving it at all.
/// </summary>
private bool TryInvoke()
{
    if (!QuickInvocation.TryParse(FilterText, out var invocation) ||
        _store.FindByQuickCode(invocation.Code) is not { } snippet)
        return false;

    var row = RowFor(snippet);
    if (!ReferenceEquals(_invoked, row)) ClearArguments();

    _invoked = row;
    var variables = KlippyVariables.Current;
    row.SetArguments(invocation.ValuesFor(snippet.Content, variables), variables);

    Filtered.Clear();
    Filtered.Add(row);
    SnippetCountText = "1 snippet";
    return true;
}

/// <summary>Takes the arguments back off the row that last had them.</summary>
private void ClearArguments()
{
    _invoked?.SetArguments(Array.Empty<string>());
    _invoked = null;
}

private SnippetViewModel RowFor(Snippet snippet)
{
    if (!_rowCache.TryGetValue(snippet.Id, out var row))
        _rowCache[snippet.Id] = row = new SnippetViewModel(snippet);
    return row;
}

private void RefreshHistory()
{
    ClearArguments(); // a snippet's arguments mean nothing against clips
    Filtered.Clear();
    if (_history is null) return;

    foreach (var entry in _history.Search(FilterText))
    {
        if (!_clipCache.TryGetValue(entry.Item.Id, out var row))
            _clipCache[entry.Item.Id] = row = new ClipViewModel(entry.Item, _history.TryLoadImage);
        else
            row.NotifyModelChanged(); // pin state and age move under the row
        Filtered.Add(row);
    }

    // Rows cached for evicted clips would otherwise accumulate for the whole session.
    if (_clipCache.Count > _history.Count * 2)
        PruneClipCache();

    SnippetCountText = Filtered.Count == 1 ? "1 clip" : $"{Filtered.Count} clips";
}

private void PruneClipCache()
{
    var live = new HashSet<Guid>();
    foreach (var clip in _history!.Entries) live.Add(clip.Id);

    foreach (var id in new List<Guid>(_clipCache.Keys))
        if (!live.Contains(id))
            _clipCache.Remove(id);
}

private void RebuildTags()
{
    Tags.Clear();
    if (HasHistory)
        Tags.Add(new TagChipViewModel(HistoryTag, IsHistoryMode, isMode: true));
    Tags.Add(new TagChipViewModel(AllTag, !IsHistoryMode && _activeTag == AllTag));
    bool activeStillExists = _activeTag == AllTag;
    foreach (var tag in _store.Tags())
    {
        bool isActive = string.Equals(tag, _activeTag, StringComparison.OrdinalIgnoreCase);
        activeStillExists |= isActive;
        Tags.Add(new TagChipViewModel(tag, !IsHistoryMode && isActive));
    }
    // e.g. the last snippet with the active tag was deleted
    if (!activeStillExists)
    {
        _activeTag = AllTag;
        if (!IsHistoryMode) ActivateTag(AllTag);
    }
}

[RelayCommand]
private void SelectTag(TagChipViewModel chip)
{
    // The History chip switches what the list shows; every other chip filters it.
    // Both leave the search box empty, since a search spans whatever the current mode
    // holds and the chips must always describe what the list is actually doing.
    if (chip.IsMode) ShowHistory();
    else ShowMode(history: false, chip.Name);
}

/// <summary>
/// Switches the list to the clipboard history. Public because a global hotkey summons
/// this view directly, without any chip being clicked. No-op where there is no history.
/// </summary>
public void ShowHistory()
{
    if (!HasHistory) return;
    ShowMode(history: true, HistoryTag);
}

/// <summary>Switches the list back to saved snippets, showing every tag.</summary>
public void ShowSnippets() => ShowMode(history: false, AllTag);

private void ShowMode(bool history, string tag)
{
    // The MRU belongs to the snippet command line, and leaving it this way is leaving
    // it empty-handed: the box goes back to what was actually typed rather than to
    // whichever recalled command was under the cursor when the view changed.
    CloseCommands(restore: true);

    // Whether this changes what the list holds or only narrows it. Asked before
    // IsHistoryMode moves, or the answer would always be "only narrows it".
    bool narrowing = history == IsHistoryMode;

    IsHistoryMode = history;
    ActivateTag(tag);

    // What is in the box survives a change of mode: you are looking for the same
    // thing either way — "that connection string" is a question for the clips and for
    // the snippets alike — and retyping it to ask the other half is an errand. A tag
    // chip is not a change of mode but a narrowing of the one you are already in, and
    // it still clears, because a search drops the tag filter the moment you type and
    // the chips have to keep describing what the list is doing.
    if (narrowing) FilterText = "";

    Refresh(); // FilterText may already have been empty, so nothing fired above
}

/// <summary>Makes <paramref name="tag"/> the active filter and moves the chip highlight to it.</summary>
private void ActivateTag(string tag)
{
    if (tag != HistoryTag) _activeTag = tag;
    foreach (var t in Tags)
        t.IsSelected = string.Equals(t.Name, tag, StringComparison.Ordinal);
}

/// <summary>
/// The item's own action: one marked Execute runs, everything else is copied. Enter,
/// a click and a tap all come through here, so what an item does is a property of
/// the item rather than of how you reached it.
/// </summary>
[RelayCommand]
private Task Activate(RowViewModel? row) =>
    row is { IsExecutable: true } ? Execute(row) : Copy(row);

[RelayCommand]
private Task ActivateSelected() => Activate(SelectedSnippet);

[RelayCommand]
private Task Copy(RowViewModel? row) => CopyCore(row, record: true);

/// <summary>
/// Puts the item on the clipboard. <paramref name="record"/> says whether what is in the search box is the
/// line that chose it, and so belongs in the command MRU — false for a shortcut, which names the snippet
/// itself and has nothing to do with whatever happens to be typed. <paramref name="quiet"/> leaves the
/// window as it is — no focus moved, nothing closed — for a hotkey pressed while an overlay is up. True
/// when something was copied.
/// </summary>
private async Task<bool> CopyCore(RowViewModel? row, bool record, bool quiet = false)
{
    CloseCommands(restore: false); // whatever route got here, the line has been chosen

    CopyPayload payload;
    if (row is SnippetViewModel snippet)
    {
        // Local defines first, then macros, which is the order the execute path
        // resolves them in and for the same reason: a %ws% that arrives through %C%
        // is a value off the clipboard rather than a name the item asked to have
        // resolved.
        var template = KlippyVariables.Current.Expand(snippet.Model.Content);

        // Macros resolve on the way to the clipboard, so what lands there is the
        // expansion — a half-typed invocation must never paste as "%P%".
        var content = await ResolveMacrosAsync(template, snippet.Arguments);
        payload = RichTextClipboard.BuildPayload(content, snippet.Model.IsMarkdown);
    }
    // A clip keeps whatever flavours it was captured with, so pasting it back gives
    // what the original copy would have — real files into Explorer, a picture into
    // an image editor, formatting into a rich-text box.
    else if (row is ClipViewModel clip) payload = BuildClipPayload(clip);
    else return false;

    if (ClipboardWriter is { } write)
        await write(payload);

    MarkUsed(row);
    if (record) RecordCommand();

    ShowToast();
    if (quiet) return true;
    Copied?.Invoke();

    // Read per copy rather than cached: the Settings overlay writes straight through
    // to the same instance, so a toggle applies to the very next copy.
    bool close = row is ClipViewModel
        ? _prefs.CloseAfterClipboardCopy
        : _prefs.CloseAfterSnippetCopy;
    if (close) CloseRequested?.Invoke();
    return true;
}

/// <summary>
/// Runs the item: its link opens in whatever opens its kind, or the document,
/// script or application it names opens or starts, with the same macros a copy would
/// have resolved.
/// Reached by triggering an item marked Execute.
///
/// The item's stored text goes to the execution engine together with the typed
/// arguments, rather than the expansion a copy would make — only the engine knows
/// whether a value is about to land in a URL's query string or in a script's
/// argument list, and those want it escaped differently.
/// </summary>
[RelayCommand]
private Task Execute(RowViewModel? row) => ExecuteCore(row, record: true);

/// <summary>
/// Runs the item — see <see cref="Execute"/>. <paramref name="record"/> and <paramref name="quiet"/> as for
/// <see cref="CopyCore"/>. True when it started.
/// </summary>
private async Task<bool> ExecuteCore(RowViewModel? row, bool record, bool quiet = false)
{
    if (row is null) return false;

    CloseCommands(restore: false);

    if (Executor is not { } run)
    {
        // Nothing wired up to run things: say so rather than leaving Enter looking
        // broken on an item that is marked to run.
        ShowToast(CannotExecuteHere, isError: true);
        return false;
    }

    var text = row.Template;

    // The variables file sits in front of the machine's own environment, so %ws% names
    // WebStorm on the run path exactly as %LOCALAPPDATA% names a folder. Handing it to
    // the policy rather than expanding here keeps the first-word-only rule: an
    // argument's percent signs stay the user's own.
    var plan = WithPreferences(ExecutionPolicy.Plan(
        text,
        row.Arguments,
        await ReadClipboardForAsync(text),
        environment: KlippyVariables.Current.Ahead(EnvironmentProbe.Real),
        alsoOpens: _prefs.AlsoOpens)) with
    {
        // The item's own marker, unlike the preferences: whether this one needs the
        // administrator's rights is a fact about it. Whether it can have them — a
        // script or an application, on Windows — is the launcher's to judge, and a
        // plan that cannot is refused there rather than started without them.
        Elevated = row.RunsAsAdministrator,
    };

    if (plan.Kind == ExecutionKind.None)
    {
        ShowToast(plan.Problem, isError: true);
        return false;
    }

    var result = await run(plan);
    ShowToast(result.Message, isError: !result.Started);
    if (!result.Started) return false;

    MarkUsed(row);
    if (record) RecordCommand();
    if (quiet) return true;
    Copied?.Invoke();

    // Executing is a launcher gesture: the browser or the script is where you are
    // going next, so Klippy gets out of the way — the copy preferences are about
    // staying put to copy a second thing, which does not apply here.
    CloseRequested?.Invoke();
    return true;
}

[RelayCommand]
private Task ExecuteSelected() => Execute(SelectedSnippet);

/// <summary>
/// Shows the file or folder a row names in Explorer or Finder: a folder opens, a file is
/// selected in the folder it is in. Any row may ask, marked or not, snippet or clip —
/// showing something runs nothing, so it needs no marker to have been put there first.
///
/// A snippet is read as a copy would put it on the clipboard, variables and macros
/// filled in, since that text is what the row stands for. A clip of files shows the
/// first of them, which is the one its row is named after; a clip of text is the path
/// it holds, read as if it had been pasted into the search box.
/// </summary>
[RelayCommand]
private async Task Reveal(RowViewModel? row)
{
    if (row is null) return;

    CloseCommands(restore: false);

    if (Executor is not { } run)
    {
        ShowToast(CannotExecuteHere, isError: true);
        return;
    }

    var text = row switch
    {
        SnippetViewModel snippet => await ResolveMacrosAsync(
            KlippyVariables.Current.Expand(snippet.Model.Content), snippet.Arguments),
        ClipViewModel { Model.Kind: ClipKind.Files, Model.Files: [var first, ..] } => first,
        ClipViewModel { Model.Kind: ClipKind.Text } clip => clip.Content,
        _ => null, // a picture, or a file clip with no files: nothing on disk to point at
    };

    var plan = ExecutionPolicy.PlanReveal(
        text, environment: KlippyVariables.Current.Ahead(EnvironmentProbe.Real));

    if (plan.Kind == ExecutionKind.None)
    {
        ShowToast(plan.Problem, isError: true);
        return;
    }

    var result = await run(plan);
    ShowToast(result.Message, isError: !result.Started);
    if (!result.Started) return;

    // Not marked as used, and nothing recorded: looking at where a file is leaves what
    // the item is for where it was. The window gets out of the way as it does for a
    // run, since the file manager is where you are going next.
    Copied?.Invoke();
    CloseRequested?.Invoke();
}

[RelayCommand]
private Task RevealSelected() => Reveal(SelectedSnippet);

/// <summary>
/// Stamps the preferences about *how* to run onto a plan the policy has just worked
/// out from what to run. Read per run rather than cached, as the copy preferences are:
/// the Settings overlay writes through to the same instance, so a toggle applies to
/// the very next Enter.
/// </summary>
private ExecutionPlan WithPreferences(ExecutionPlan plan) =>
    plan with { PullFirst = _prefs.ExecutePullFirst };

/// <summary>Fills in an item's macros, reading the clipboard only if it carries a %C%.</summary>
private async Task<string> ResolveMacrosAsync(string text, IReadOnlyList<string> arguments)
{
    if (!Macros.IsPresent(text)) return text;
    return Macros.Expand(text, arguments, await ReadClipboardForAsync(text));
}

/// <summary>
/// The clipboard's text when <paramref name="text"/> needs it, null otherwise — which
/// leaves any %C% as written rather than silently emptying it.
/// </summary>
private async Task<string?> ReadClipboardForAsync(string text)
{
    if (!Macros.UsesClipboard(text) || ClipboardReader is not { } read) return null;

    // An empty clipboard is an empty expansion, not a missing one.
    return await read() ?? "";
}

/// <summary>Bumps recency, so what you just used ranks first next time.</summary>
private void MarkUsed(RowViewModel row)
{
    if (row is SnippetViewModel snippet) _store.MarkUsed(snippet.Model);
    // Re-using a clip promotes it back to the top, exactly as capture would — and has
    // to say so, since Klippy's own clipboard writes are never captured.
    else if (row is ClipViewModel clip) _history?.MarkUsed(clip.Model.Id);
}

private CopyPayload BuildClipPayload(ClipViewModel clip) => clip.Model.Kind switch
{
    ClipKind.Files => new CopyPayload(clip.Model.Text, null) { Files = clip.Model.Files },
    ClipKind.Image => new CopyPayload("", null)
    {
        Image = _history?.TryLoadImage(clip.Model),
        ImageFormat = clip.Model.BlobFormat,
    },
    _ => new CopyPayload(clip.Model.Text, clip.Model.Html),
};

/// <summary>
/// Whether one of the matching rows <em>is</em> what was typed rather than merely
/// mentioning it — by the line as typed, or by what that line resolved to, so
/// <c>%APPDATA%</c> and the folder it expands to are the same request.
/// </summary>
private bool AnItemIsTheLine(ExecutionPlan plan)
{
    var typed = UnmatchedSearch.Unquote(FilterText.Trim());

    foreach (var row in Filtered)
        if (Names(row.Label, typed) || Names(row.Content, typed)
            || Names(row.Label, plan.Target) || Names(row.Content, plan.Target))
            return true;

    return false;
}

private static bool Names(string? text, string wanted) =>
    wanted.Length > 0 && string.Equals(text?.Trim(), wanted, StringComparison.OrdinalIgnoreCase);

/// <summary>
/// Runs an offer, or puts a machine control up for confirmation first: the one clicked,
/// or — from Enter, which names none — the one holding the selection, and failing that
/// the one at the top.
///
/// Only ever reachable while something is on offer, and Enter only comes here while no
/// row holds the selection — so this can never fire instead of a copy.
/// </summary>
[RelayCommand]
private Task RunOffer(OfferViewModel? offer)
{
    if ((offer ?? SelectedOffer ?? Offer) is not { } chosen) return Task.CompletedTask;

    if (!chosen.NeedsConfirmation(_prefs)) return Run(chosen);

    PendingOffer = chosen;
    return Task.CompletedTask;
}

/// <summary>Goes ahead with a machine control the user has confirmed.</summary>
[RelayCommand]
private Task ConfirmOffer()
{
    if (PendingOffer is not { } offer) return Task.CompletedTask;
    PendingOffer = null;
    return Run(offer);
}

[RelayCommand]
private void CancelOffer() => PendingOffer = null;

/// <summary>
/// Asks to close Klippy, from the footer link rather than the typed word — the route
/// for a pointer already down there, and the one that still works when a snippet
/// called "quit" has taken the word.
///
/// It puts up the same confirmation the offer does rather than a second dialog of its
/// own: one question, however it was asked.
/// </summary>
[RelayCommand]
private void RequestQuit()
{
    if (CanQuit) PendingOffer = OfferViewModel.Quit();
}

/// <summary>
/// Hands the offer's plan to the same engine an item marked Execute goes through, and
/// reports in the same toast. The only difference is where the plan came from.
///
/// Quit is the one offer with no plan to hand over: it is Klippy closing rather than
/// Klippy starting something, so it turns back here and never reaches the launcher.
/// </summary>
private async Task Run(OfferViewModel offer)
{
    CloseCommands(restore: false);

    if (offer.IsQuit)
    {
        QuitRequested?.Invoke();
        return;
    }

    if (Executor is not { } run)
    {
        ShowToast(CannotExecuteHere, isError: true);
        return;
    }

    var result = await run(WithPreferences(offer.Plan));
    ShowToast(result.Message, isError: !result.Started);
    if (!result.Started) return; // the window stays up, or the message is never read

    RecordCommand();

    // Executing is a launcher gesture: whatever just started is where the user is
    // going next, and for a machine control there is nothing left here to look at.
    CloseRequested?.Invoke();
}

/// <summary>Keeps a clip out of the history's eviction, or releases it.</summary>
[RelayCommand]
private void TogglePin(ClipViewModel? row)
{
    if (row is null || _history is null) return;
    _history.SetPinned(row.Model.Id, !row.Model.IsPinned);
    Refresh();
}

/// <summary>
/// Drops a clip. No confirmation, unlike deleting a snippet: a clip is transient by
/// nature and the next copy makes another, so the gesture does not deserve a dialog.
/// </summary>
[RelayCommand]
private void DeleteClip(ClipViewModel? row)
{
    if (row is null || _history is null) return;
    _history.Remove(row.Model.Id);
    Refresh();
}

/// <summary>Empties the history, keeping pinned clips.</summary>
[RelayCommand]
private void ClearHistory()
{
    _history?.Clear();
    Refresh();
}

/// <summary>
/// Opens the snippet editor prefilled from a clip — the bridge between the two halves
/// of the app, and the reason a clipboard history belongs in a snippet manager at all.
/// The clip stays in the history; saving creates a snippet beside it.
/// </summary>
[RelayCommand]
private void PromoteToSnippet(ClipViewModel? row)
{
    // A snippet is text, so a picture has nothing to promote into one. File clips do:
    // their paths are the text.
    if (row is null || row.Model.Kind == ClipKind.Image) return;

    var editor = NewEditor(null, title: "New snippet from clip");
    editor.Label = row.Label;
    editor.Content = row.Model.Text;
    editor.IsMarkdown = false; // captured text is not known to be Markdown
    Editor = editor;
}

[RelayCommand]
private Task CopySelected() => Copy(SelectedSnippet);

/// <summary>
/// Moves the selection through the list — and, where there are offers standing above
/// it, on and off those too. They are one column: the rows from 0 down, and the offers
/// at -1, -2 and on up the window from the list. The up arrow has to be able to get back
/// to them, or looking at what else matched would put what Enter was going to run
/// permanently out of reach.
/// </summary>
public void MoveSelection(int delta)
{
    if (Filtered.Count == 0 && Offers.Count == 0) return;

    int position = SelectedSnippet is { } row ? Filtered.IndexOf(row)
        : Offers.Count > 0 ? _offerIndex - Offers.Count
        : -1;
    position = Math.Clamp(position + delta, -Offers.Count, Filtered.Count - 1);

    if (position >= 0)
    {
        SelectedSnippet = Filtered[position];
        return;
    }

    _offerIndex = position + Offers.Count;
    SelectedSnippet = null;
    SyncOfferSelection(); // the selection may have moved between two offers, which no row noticed
}

// ---- the command MRU ----
//
// One pair of arrow keys, two lists that could want them. The rule is that the MRU
// has them only while it is open, and it is only open when it has something to say:
// a down arrow on an empty box, or a typed line that is the start of a command run
// before. Anything else leaves ↑/↓ to the snippet list, where they have always been.

/// <summary>
/// Down or up: the MRU while it is open, otherwise the list — and, from an empty
/// search box, a down arrow opens the MRU rather than stepping past the first row,
/// since an unfiltered list has nothing to step through that recency has not already
/// put at the top.
/// </summary>
public void Navigate(int delta)
{
    if (IsCommandsOpen)
    {
        MoveCommandSelection(delta);
        return;
    }

    if (delta > 0 && FilterText.Length == 0 && OpenCommands(selectFirst: true)) return;

    MoveSelection(delta);
}

/// <summary>
/// Offers the commands the typed

    /// way to have it with an empty <c>%C%</c>, for whoever wants that.
    /// </summary>
    public async Task<TriggerOutcome> TriggerSnippetAsync(Guid id)
    {
        if (_store.Find(id) is not { } snippet) return TriggerOutcome.Failed;

        // The variables file first, as copy and run apply it: a define can be what brings the %P%.
        var expanded = KlippyVariables.Current.Expand(snippet.Content);
        if (Macros.TakesArguments(expanded))
            return PromptForArguments(snippet);

        if (Macros.UsesClipboard(expanded) && !await ClipboardHasTextAsync())
        {
            ShowToast($"\u201c{snippet.Label}\u201d uses the clipboard, and there's no text on it — copy some, " +
                      "then press its keys again.", isError: true);
            return TriggerOutcome.Failed;
        }

        // A fresh row rather than the list's own: the list's may be carrying arguments typed after its
        // quick-code, and a shortcut names the snippet, not that line.
        var row = new SnippetViewModel(snippet);

        // Only a system-wide hotkey gets here with an overlay up — the in-window shortcuts stand aside for one.
        // It still does its job, but leaves the window be: the keyboard stays in the editor, where a snippet
        // copied by hotkey is as likely as not about to be pasted, and nothing closes mid-edit.
        var quiet = IsOverlayOpen;
        var done = snippet.IsExecutable
            ? await ExecuteCore(row, record: false, quiet)
            : await CopyCore(row, record: false, quiet);
        return done ? TriggerOutcome.Done : TriggerOutcome.Failed;
    }

    /// <summary>
    /// Whether the clipboard holds text for a <c>%C%</c> — not nothing, not a picture or files, not just
    /// whitespace. Read here and again when the snippet resolves: a second read is cheap, and threading the
    /// first one through copy and run would buy nothing but a moment's difference.
    /// </summary>
    private async Task<bool> ClipboardHasTextAsync() =>
        ClipboardReader is { } read && !string.IsNullOrWhiteSpace(await read());

    /// <summary>
    /// Puts <paramref name="snippet"/>'s quick-code in the search box, ready for its argument — or, where it
    /// can't, says why. Arguments are typed after a quick-code, so a snippet without one has nowhere to take
    /// them; and an overlay up (a hotkey pressed from the editor) is not torn down for it.
    /// </summary>
    private TriggerOutcome PromptForArguments(Snippet snippet)
    {
        if (IsOverlayOpen)
        {
            ShowToast($"\u201c{snippet.Label}\u201d takes an argument — close this first, then press its keys again.",
                isError: true);
            return TriggerOutcome.Failed;
        }

        if (snippet.QuickCode.Length == 0)
        {
            ShowToast($"\u201c{snippet.Label}\u201d takes an argument, which is typed after a quick-code — " +
                      "give it one in the editor.", isError: true);
            return TriggerOutcome.Failed;
        }

        if (IsHistoryMode) ShowSnippets();
        CloseCommands(restore: false);
        FilterText = snippet.QuickCode + " ";
        ArgumentsRequested?.Invoke();
        return TriggerOutcome.AwaitingArguments;
    }

    /// <summary>Whether an overlay — the editor, a confirmation, export/import, settings — is up.</summary>
    private bool IsOverlayOpen =>
        Editor is not null || DeleteTarget is not null || Transfer is not null || Settings is not null
        || PendingOffer is not null || ImagePreview is not null;

    /// <summary>
    /// A registered system-wide hotkey was pressed while one of the editor's key fields is listening — so the
    /// OS handed it to Klippy instead of to the field. Gives it to the field, as the press it was. True when
    /// the editor took it, and the hotkey should do nothing else.
    /// </summary>
    public bool OfferHotkeyToRecorder(HotkeySpec spec)
    {
        if (Editor is not { IsRecording: true } editor) return false;
        editor.Press(SnippetHotkeys.ToStroke(spec));
        return true;
    }

    /// <summary>The system-wide hotkeys to register: one per snippet that asks for one, clashes settled.</summary>
    public IReadOnlyList<(Guid SnippetId, HotkeySpec Spec)> PlannedHotkeys() =>
        SnippetHotkeys.Plan(_store.Snippets, SummonKeys);

    /// <summary>Klippy's own two summon keys, which no snippet may take.</summary>
    private IEnumerable<HotkeySpec?> SummonKeys => [_prefs.ParsedHotkey, _prefs.ParsedHistoryHotkey];

    /// <summary>
    /// The launcher's answer to <see cref="PlannedHotkeys"/>: the snippets whose hotkey it could not claim,
    /// because another application holds the combination. The editor says so for those.
    /// </summary>
    public void ReportUnclaimedHotkeys(IEnumerable<Guid> snippetIds)
    {
        _unclaimedHotkeys.Clear();
        _unclaimedHotkeys.UnionWith(snippetIds);
    }

    /// <summary>Whether the snippet's hotkey is one the launcher tried, and failed, to claim.</summary>
    public bool IsHotkeyUnclaimed(Guid snippetId) => _unclaimedHotkeys.Contains(snippetId);

    private void OnSnippetsChanged()
    {
        RebuildShortcuts();
        SnippetsChanged?.Invoke();
    }

    /// <summary>
    /// Rebuilds the in-Klippy shortcuts. The system-wide keys are left out of them: the OS hands a press on
    /// one of those to Klippy's hotkey before the window ever sees it.
    /// </summary>
    private void RebuildShortcuts()
    {
        var globals = new HashSet<HotkeySpec>(SummonKeys.OfType<HotkeySpec>());
        if (CanRegisterHotkeys)
            globals.UnionWith(PlannedHotkeys().Select(p => p.Spec));

        _shortcuts = SnippetShortcutMap.Build(_store.Snippets, globals);
        _chords.Map = _shortcuts;
        ClearChordStatus();
        OnPropertyChanged(nameof(IsChordPending));
    }

    /// <summary>What the editor needs to say about keys: who else has which, and what Klippy keeps for itself.</summary>
    private SnippetKeysContext KeysContextFor(Snippet? existing) => new(
        Others: _store.Snippets.Where(s => existing is null || s.Id != existing.Id).ToList(),
        SnippetsKey: _prefs.ParsedHotkey,
        HistoryKey: _prefs.ParsedHistoryHotkey,
        CanRegisterHotkeys: CanRegisterHotkeys,
        HotkeyUnclaimed: existing is not null && IsHotkeyUnclaimed(existing.Id));

    /// <summary>
    /// Takes the saved snippet's keys from any other snippet that had them — the same in-Klippy keys, or one
    /// where the other's chord starts, and the same system-wide hotkey. The editor named them before Save.
    /// </summary>
    private void TakeKeysFromOthers(Snippet saved)
    {
        var hasShortcut = Shortcut.TryParse(saved.Shortcut, out var mine);
        var hasHotkey = SnippetHotkeys.TryRead(saved.Hotkey, out var myHotkey);
        if (!hasShortcut && !hasHotkey) return;

        foreach (var other in _store.Snippets.ToList())
        {
            if (other.Id == saved.Id) continue;

            var changed = false;
            if (hasShortcut && Shortcut.TryParse(other.Shortcut, out var theirs) && theirs.CollidesWith(mine))
            {
                other.Shortcut = "";
                changed = true;
            }
            if (hasHotkey && SnippetHotkeys.TryRead(other.Hotkey, out var theirHotkey) && theirHotkey == myHotkey)
            {
                other.Hotkey = "";
                changed = true;
            }
            if (!changed) continue;

            _store.Update(other);
            if (_rowCache.TryGetValue(other.Id, out var row)) row.NotifyModelChanged();
        }
    }

    /// <summary>
    /// After a save, says so when the snippet's hotkey could not be claimed — the launcher re-registered on
    /// <see cref="SnippetsChanged"/>, so the answer is already in.
    /// </summary>
    private void ReportUnclaimedHotkey(Snippet saved)
    {
        if (CanRegisterHotkeys && IsHotkeyUnclaimed(saved.Id) && SnippetHotkeys.TryRead(saved.Hotkey, out var spec))
            ShowToast($"Another application holds {spec}, so it won't trigger \"{saved.Label}\" — pick another.",
                isError: true);
    }
}

