using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Klippy.ViewModels;

namespace Klippy.Views;

public partial class ImagePreviewOverlay : UserControl
{
    private IInputElement? _returnTo;

    public ImagePreviewOverlay()
    {
        InitializeComponent();

        // Tab goes round the buttons rather than out to the list behind the scrim, and the
        // keyboard starts on Copy image — the one thing here that is undone by copying again.
        KeyboardNavigation.SetTabNavigation(Overlay, KeyboardNavigationMode.Cycle);
        Overlay.PropertyChanged += (_, e) =>
        {
            if (e.Property != Visual.IsVisibleProperty) return;

            if (Overlay.IsVisible)
            {
                _returnTo = TopLevel.GetTopLevel(Overlay)?.FocusManager?.GetFocusedElement();
                CopyButton.Focus(NavigationMethod.Tab);
            }
            else
            {
                if (_returnTo is Visual previous && TopLevel.GetTopLevel(previous) is not null)
                    _returnTo.Focus();
                _returnTo = null;
            }
        };
    }

    private void ScrimPressed(object? sender, PointerPressedEventArgs e)
    {
        if (DataContext is MainViewModel vm)
            vm.CloseImagePreviewCommand.Execute(null);
    }
}

    /// after it. False when the line is not an invocation — no whitespace yet, or no
    /// snippet answers to that exact code — and the ordinary search runs instead.
    ///
    /// The variables file comes along, so an argument can name a define rather than
    /// spelling a path out: "r app" is the solution app names. Against the snippet as
    /// stored, because the item is half of the question — its %P:file% is what says which
    /// flavour of a name it wants. Resolved once, here, so the row's preview, a copy and a
    /// run all see the same argument: having them disagree about what a word meant would
    /// be worse than not resolving it at all.
    /// </summary>
    private bool TryInvoke()
    {
        if (!QuickInvocation.TryParse(FilterText, out var invocation) ||
            _store.FindByQuickCode(invocation.Code) is not { } snippet)
            return false;

        var row = RowFor(snippet);
        if (!ReferenceEquals(_invoked, row)) ClearArguments();

        _invoked = row;
        var variables = KlippyVariables.Current;
        row.SetArguments(invocation.ValuesFor(snippet.Content, variables), variables);

        Filtered.Clear();
        Filtered.Add(row);
        SnippetCountText = "1 snippet";
        return true;
    }

    /// <summary>Takes the arguments back off the row that last had them.</summary>
    private void ClearArguments()
    {
        _invoked?.SetArguments(Array.Empty<string>());
        _invoked = null;
    }

    private SnippetViewModel RowFor(Snippet snippet)
    {
        if (!_rowCache.TryGetValue(snippet.Id, out var row))
            _rowCache[snippet.Id] = row = new SnippetViewModel(snippet);
        return row;
    }

    private void RefreshHistory()
    {
        ClearArguments(); // a snippet's arguments mean nothing against clips
        Filtered.Clear();
        if (_history is null) return;

        foreach (var entry in _history.Search(FilterText))
        {
            if (!_clipCache.TryGetValue(entry.Item.Id, out var row))
                _clipCache[entry.Item.Id] = row = new ClipViewModel(entry.Item, _history.TryLoadImage);
            else
                row.NotifyModelChanged(); // pin state and age move under the row
            Filtered.Add(row);
        }

        // Rows cached for evicted clips would otherwise accumulate for the whole session.
        if (_clipCache.Count > _history.Count * 2)
            PruneClipCache();

        SnippetCountText = Filtered.Count == 1 ? "1 clip" : $"{Filtered.Count} clips";
    }

    private void PruneClipCache()
    {
        var live = new HashSet<Guid>();
        foreach (var clip in _history!.Entries) live.Add(clip.Id);

        foreach (var id in new List<Guid>(_clipCache.Keys))
            if (!live.Contains(id))
                _clipCache.Remove(id);
    }

